-- Semantic embeddings generated from QA2.csv
-- Model: sentence-transformers/paraphrase-multilingual-mpnet-base-v2
-- Embedding dimension: 768; normalized for cosine similarity
create extension if not exists vector with schema extensions;

create table if not exists public.qa (
    id bigint primary key,
    category text not null,
    question text not null,
    answer text not null,
    embedding extensions.vector(768) not null
);

-- Upsert rows by id so this script can be run again safely.

create index if not exists qa_embedding_cosine_idx
    on public.qa using hnsw (embedding extensions.vector_cosine_ops);
